import flint

from .runner import find_hacs, hacs_version, oc_matrix, provenance, run_script

SCRIPT = "code/python/langlandscape/hacs_bridge/definite_alg.py"
MIN_PRIMES = 4
PRIME_CAP = 19
MAX_RANK = 100  # R7: rank^2 <= 10^4 entries per literal


# =====================================================================================================================
# Part 1: pure-Python F_l-algebra toolkit (independent of HACS)
# =====================================================================================================================
def _nm(rows, l):
    """nmod_mat from a list of integer rows."""
    n = len(rows)
    m = len(rows[0]) if n else 0
    return flint.nmod_mat(n, m, [int(x) % l for r in rows for x in r], l)


def _rows(M):
    return [[int(M[i, j]) for j in range(M.ncols())] for i in range(M.nrows())]


def _ident(n, l):
    return _nm([[int(i == j) for j in range(n)] for i in range(n)], l)


def _kernel_cols(A):
    """Basis of ker A (A acts on columns) as a list of column vectors (lists)."""
    X, nullity = A.nullspace()
    return [[int(X[i, j]) for i in range(X.nrows())] for j in range(nullity)]


def _poly_eval(f, X, l):
    """f(X) for an nmod_poly f and an nmod_mat X (Horner)."""
    n = X.nrows()
    R = _nm([[0] * n for _ in range(n)], l)
    I = _ident(n, l)
    for c in reversed(f.coeffs()):
        R = R * X + I * int(c)
    return R


def restrict(g, K, l):
    """Matrix of g on the g-stable subspace spanned by the columns ``K`` (list of column vectors)."""
    n, s = g.nrows(), len(K)
    W = _nm([[K[j][i] for j in range(s)] for i in range(n)], l)  # n x s
    GW = g * W
    # pick s rows J with W[J] invertible
    Wt = W.transpose().rref()[0]
    piv, r = [], 0
    for i in range(Wt.nrows()):
        j = next((j for j in range(n) if int(Wt[i, j]) != 0), None)
        if j is not None:
            piv.append(j)
    assert len(piv) == s, "dependent block basis"
    WJ = _nm([[int(W[j, c]) for c in range(s)] for j in piv], l)
    GJ = _nm([[int(GW[j, c]) for c in range(s)] for j in piv], l)
    X = WJ.solve(GJ)
    assert W * X == GW, "subspace is not stable"
    return X


class FlatAlgebra:
    """F_l[ops] inside M_n(F_l) (commuting ops): a basis of matrices and coordinates."""

    def __init__(self, ops, l):
        self.l, self.ops = l, ops
        n = ops[0].nrows()
        self.n = n
        I = _ident(n, l)
        basis, flats = [], []
        queue = [I]
        rk = 0
        while queue:
            M = queue.pop(0)
            fl = [int(M[i, j]) for i in range(n) for j in range(n)]
            test = _nm(flats + [fl], l)
            if test.rank() > rk:
                rk += 1
                basis.append(M)
                flats.append(fl)
                for g in ops:
                    queue.append(g * M)
        self.basis, self.flats, self.dim = basis, flats, len(basis)
        B = _nm(flats, l)  # d x n^2
        # pivot columns J with B[:, J] invertible
        R = B.rref()[0]  # pivot columns of B (d x n^2): columns J with B[:, J] invertible
        self.piv = []
        for i in range(R.nrows()):
            j = next((j for j in range(R.ncols()) if int(R[i, j]) != 0), None)
            if j is not None:
                self.piv.append(j)
        assert len(self.piv) == self.dim
        self._BJ = _nm([[flats[a][j] for a in range(self.dim)] for j in self.piv], l)  # d x d (rows = piv, cols = basis)

    def coords(self, M):
        """Coordinates of the matrix M (in the algebra) in the basis, as a column list."""
        n, l = self.n, self.l
        flat = [int(M[i, j]) for i in range(n) for j in range(n)]
        rhs = _nm([[flat[j]] for j in self.piv], l)
        c = self._BJ.solve(rhs)
        out = [int(c[a, 0]) for a in range(self.dim)]
        recon = _nm([[0] * n for _ in range(n)], l)
        for a, ca in enumerate(out):
            recon = recon + self.basis[a] * ca
        assert recon == M, "element not in the algebra"
        return out

    def frobenius_matrix(self):
        """Matrix (columns = coordinates of b_i^l) of the F_l-linear map x -> x^l."""
        cols = [self.coords(_matpow(b, self.l, self.l)) for b in self.basis]
        return _nm([[cols[j][i] for j in range(self.dim)] for i in range(self.dim)], self.l)

    def from_coords(self, c):
        R = _nm([[0] * self.n for _ in range(self.n)], self.l)
        for a, ca in enumerate(c):
            R = R + self.basis[a] * int(ca)
        return R


def _matpow(M, e, l):
    R = _ident(M.nrows(), l)
    B = M
    while e:
        if e & 1:
            R = R * B
        B = B * B
        e >>= 1
    return R


def _span_dim(mats, l):
    if not mats:
        return 0
    n = mats[0].nrows()
    return _nm([[int(M[i, j]) for i in range(n) for j in range(n)] for M in mats], l).rank()


def _span_basis(mats, l):
    """Independent subset of the matrices (greedy)."""
    out, rk = [], 0
    n = mats[0].nrows() if mats else 0
    flats = []
    for M in mats:
        fl = [int(M[i, j]) for i in range(n) for j in range(n)]
        t = _nm(flats + [fl], l)
        if t.rank() > rk:
            rk += 1
            out.append(M)
            flats.append(fl)
    return out


def local_invariants(ops, l):
    """Invariants of the commutative F_l-algebra A = F_l[ops] (pure Python, mod-l linear algebra).

    Returns dict(dim, components, local, dim_radical, residue_degree (local only), nilpotency_index (Loewy length),
    radical_power_dims, dim_tangent, dim_socle, gorenstein (dim_socle == f, local only)).
    """
    A = FlatAlgebra(ops, l)
    d = A.dim
    # radical = ker Frob^e, l^e >= d
    F = A.frobenius_matrix()
    e = 1
    while l ** e < d:
        e += 1
    Fe = _ident(d, l)
    for _ in range(e):
        Fe = F * Fe
    rad_c = _kernel_cols(Fe)
    rad = [A.from_coords(c) for c in rad_c]
    rdim = len(rad)
    # components = dim{x : x^l - x in rad} - dim rad  (number of F_l-points of A/rad = number of components)
    FI = F - _ident(d, l)
    if rdim:
        Rm = _nm([[rad_c[j][i] for j in range(rdim)] for i in range(d)], l)
        N, nn = Rm.transpose().nullspace()  # columns span {y : y^T R = 0}: linear forms vanishing on rad
        Nrows = _nm([[int(N[i, j]) for i in range(d)] for j in range(nn)], l) if nn else None
        comp = d - (Nrows * FI).rank() if Nrows is not None else d
    else:
        comp = d - FI.rank()
    components = comp - rdim
    # radical powers
    powers = [rdim]
    cur = rad
    while cur:
        nxt = _span_basis([x * y for x in cur for y in rad], l) if rad else []
        # drop zero matrices (rank test excludes them automatically)
        powers.append(len(nxt))
        cur = nxt
        if not cur:
            break
    nil = len(powers) if rdim else 1  # rad^nu = 0 with nu = number of nonzero powers (rad^1 .. rad^{nu-1} nonzero)
    # powers = [dim rad^1, dim rad^2, ..., 0]; nilpotency index = len(powers) (first j with rad^j = 0)
    rpd = powers[:-1] if powers and powers[-1] == 0 else powers
    # socle = Ann_A(rad)
    if rdim:
        rows = []
        for r in rad:
            cols = []
            for b in A.basis:
                P = b * r
                cols.append([int(P[i, j]) for i in range(A.n) for j in range(A.n)])
            rows += [[cols[a][t] for a in range(d)] for t in range(A.n * A.n)]
        soc = d - _nm(rows, l).rank()
    else:
        soc = d
    rad2 = powers[1] if len(powers) > 1 else 0
    out = {
        "dim": d, "components": components, "local": components == 1, "dim_radical": rdim,
        "nilpotency_index": nil, "radical_power_dims": rpd,
        "dim_tangent": rdim - rad2, "dim_socle": soc,
    }
    if components == 1:
        f = d - rdim
        out["residue_degree"] = f
        out["gorenstein"] = soc == f
    return out


def _factor_split(x, l):
    """Primary decomposition of the n-space w.r.t. x: list of (factor, column basis of ker f(x)^e)."""
    cp = x.charpoly()
    _c, facs = flint.nmod_poly([int(c) for c in cp.coeffs()], l).factor()
    out = []
    for f, mult in facs:
        K = _kernel_cols(_matpow_poly(f, x, mult, l))
        assert K, "empty primary component"
        out.append((f, K))
    return out


def _matpow_poly(f, x, e, l):
    F = _poly_eval(f, x, l)
    return _matpow(F, e, l)


def split_local(ops, l, seed=1):
    """Cut the algebra into local blocks; returns a list of restricted operator lists (one per maximal ideal)."""
    rng = random.Random(seed)
    todo, done = [list(ops)], []
    while todo:
        blk = todo.pop(0)
        inv = local_invariants(blk, l)
        if inv["local"]:
            done.append(blk)
            continue
        cands = list(blk)
        for _ in range(60):
            cands.append(sum_scaled(blk, [rng.randrange(l) for _ in blk], l))
        for x in cands:
            parts = _factor_split(x, l)
            if len(parts) > 1:
                for _f, K in parts:
                    todo.append([restrict(g, K, l) for g in blk])
                break
        else:  # pragma: no cover - cannot happen for l large enough, or with enough random tries
            raise RuntimeError("could not split a non-local block")
    return done


def sum_scaled(ops, coeffs, l):
    R = _nm([[0] * ops[0].nrows() for _ in range(ops[0].nrows())], l)
    for g, c in zip(ops, coeffs):
        R = R + g * int(c)
    return R


# =====================================================================================================================
# Part 2: the integral algebra T (Z-lattice generated by the T_p) and its regular representation
# =====================================================================================================================
def _flat(M):
    return [x for row in M for x in row]


def _lcm(a, b):
    return a * b // math.gcd(a, b)


def _lattice_basis(vecs):
    """HNF basis (rows, Fractions) of the Z-span of rational vectors."""
    vecs = [v for v in vecs if any(v)]
    if not vecs:
        return []
    D = 1
    for v in vecs:
        for x in v:
            D = _lcm(D, Fraction(x).denominator)
    n = len(vecs[0])
    H = flint.fmpz_mat(len(vecs), n, [int(Fraction(x) * D) for v in vecs for x in v]).hnf()
    rows = []
    for i in range(H.nrows()):
        r = [int(H[i, j]) for j in range(n)]
        if any(r):
            rows.append(tuple(Fraction(x, D) for x in r))
    return rows


def _matmul_q(A, B):
    n = len(A)
    return [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(n)] for i in range(n)]


def _unflat(v, n):
    return [[Fraction(v[i * n + j]) for j in range(n)] for i in range(n)]


def z_algebra(gens):
    """Z-basis (list of n x n rational matrices) of the unital Z-algebra generated by commuting rational matrices."""
    n = len(gens[0])
    I = [[Fraction(int(i == j)) for j in range(n)] for i in range(n)]
    basis = _lattice_basis([_flat(I)] + [_flat(g) for g in gens])
    while True:
        cand = list(basis)
        for b in basis:
            Bm = _unflat(b, n)
            for g in gens:
                cand.append(tuple(_flat(_matmul_q(Bm, g))))
        nb = _lattice_basis(cand)
        if nb == basis:
            return [_unflat(b, n) for b in basis]
        basis = nb


def regular_rep(basis, gens):
    """Integer matrices (columns = coordinates of g*b_j in the Z-basis) of g in ``gens`` on the algebra with Z-basis ``basis``."""
    n = len(basis[0])
    vecs = [tuple(_flat(b)) for b in basis]
    # basis rows are an HNF (echelon): pivot column = first nonzero entry
    piv = [next(j for j, x in enumerate(v) if x) for v in vecs]
    out = []
    for g in gens:
        cols = []
        for b in basis:
            w = list(_flat(_matmul_q(g, b)))
            c = []
            for v, pj in zip(vecs, piv):
                q = w[pj] / v[pj]
                assert q.denominator == 1, "T_p * b not in the lattice (closure failed)"
                c.append(int(q))
                w = [x - q * y for x, y in zip(w, v)]
            assert not any(w), "product not in the span"
            cols.append(c)
        r = len(basis)
        out.append([[cols[j][i] for j in range(r)] for i in range(r)])
    return out


# =====================================================================================================================
# Part 3: the definite side (Python Brandt matrices), cell driver, HACS call
# =====================================================================================================================
def _is_prime(p):
    return p > 1 and all(p % q for q in range(2, int(p ** 0.5) + 1))


def _prime_list(D, l, upto):
    return [p for p in range(2, upto + 1) if _is_prime(p) and (D * l) % p]


def _next_primes(D, l, have, cnt):
    out, p = [], (max(have) if have else 1)
    while len(out) < cnt:
        p += 1
        if _is_prime(p) and (D * l) % p:
            out.append(p)
    return out


def psi(D):
    from .. import quat

    r = 1
    for p in quat.prime_factors(D):
        r *= p + 1
    return r


def definite_matrices(D, k, primes):
    """Rational matrices of T_p, p in primes, on M(O_D; Sym^{k-2}) (x) Q (weight 2: classes basis; k > 2: via Q(sqrt a), dim 2 d)."""
    if k == 2:
        from .. import brandt

        m = brandt.module(D)
        return [[[Fraction(x) for x in row] for row in m.T(p)] for p in primes], {"h": m.h, "gammas": list(m.gammas), "a": m.B.a,
                                                                                      "model": "weight-2 Brandt module, class basis (class order of brandt.module(D).T(p))"}
    from .. import symn

    S = symn.sym_brandt(D, k)
    a = S.S.a
    mats = []
    for p in primes:
        T = S.T(p)
        d = S.dim
        M = [[Fraction(0)] * (2 * d) for _ in range(2 * d)]
        for i in range(d):
            for j in range(d):
                z = T[i][j]
                M[2 * i][2 * j], M[2 * i][2 * j + 1] = z.r, a * z.s
                M[2 * i + 1][2 * j], M[2 * i + 1][2 * j + 1] = z.s, z.r
        mats.append(M)
    return mats, {"h": S.h, "gammas": list(S.gammas), "a": a, "dim_M_over_K": S.dim,
                  "model": "Sym^{k-2} Brandt module over Q(sqrt a), viewed as a Q-space of dim 2 dim M"}


def _legendre_kind(a, l):
    """How l decomposes in Q(sqrt a): 'ramified', 'split', 'inert' (l odd; l = 2 treated by the field discriminant)."""
    d = a if a % 4 == 1 else 4 * a
    if d % l == 0:
        return "ramified"
    if l == 2:
        return "split" if d % 8 == 1 else "inert"
    return "split" if pow(a % l, (l - 1) // 2, l) == 1 else "inert"


def _label(ops, l):
    """Per generator: the eigenvalue c (charpoly (x - c)^dim) if linear, else the irreducible factor (coefficients low -> high)."""
    out = []
    for g in ops:
        _c, facs = flint.nmod_poly([int(c) for c in g.charpoly().coeffs()], l).factor()
        f = facs[0][0]
        out.append((-int(f.coeffs()[0])) % l if f.degree() == 1 else [int(c) for c in f.coeffs()])
    return out


def _is_eisenstein(ops, primes, l):
    """Block is the Eisenstein ideal: T_p - (1 + p) nilpotent for every p (weight 2)."""
    for g, p in zip(ops, primes):
        n = g.nrows()
        X = g - _ident(n, l) * (1 + p)
        if _matpow(X, n, l) != _nm([[0] * n for _ in range(n)], l):
            return False
    return True


def _oc_script(l, whole, blocks, gens_coeffs):
    """.oc source: whole algebra + per block invariants, loewy, minpoly of a generic element."""
    lines = []
    lines.append("W = [" + ", ".join(oc_matrix(l, g) for g in whole) + "];")
    lines.append('print("@@WHOLE " + json(algebra_invariants(W)));')
    for i, (ops, co) in enumerate(zip(blocks, gens_coeffs)):
        lines.append("B = [" + ", ".join(oc_matrix(l, g) for g in ops) + "];")
        lines.append("x = " + _combo_expr(len(ops), co) + ";")
        lines.append('print("@@INV " + json(algebra_invariants(B)));')
        lines.append('print("@@LOEWY " + json(loewy(B)));')
        lines.append('print("@@MINPOLY " + json(coeffs(minpoly(x))));')
    return "\n".join(lines) + "\n"


def _combo_expr(n, co):
    return _sum_expr([f"scale(B[{i}], {c})" for i, c in enumerate(co)])


def _sum_expr(terms):
    e = terms[0]
    for t in terms[1:]:
        e = f"add({e}, {t})"
    return e


def _generic_coeffs(ops, l):
    """Unit vector at the generator of largest minimal-polynomial degree (a random combination can cancel the nilpotent part)."""
    degs = [len(_py_minpoly([g], [1], l)) for g in ops]
    i = max(range(len(ops)), key=lambda j: (degs[j], -j))
    return [int(j == i) for j in range(len(ops))]


def _py_minpoly(ops, co, l):
    x = sum_scaled(ops, co, l)
    return [int(c) for c in x.minpoly().coeffs()]


def _cmp_keys(py, hx):
    """Compare the python invariants with HACS's record; returns the list of disagreeing keys."""
    keys = ["dim", "local", "dim_radical", "nilpotency_index", "dim_tangent", "dim_socle", "residue_degree", "gorenstein"]
    return [k for k in keys if k in py and py[k] != hx.get(k)]


def run_cell(D, k, l, *, hacs=None, threads=4, extra=2):
    """One cell (D, k, l).  Returns the result record; raises AssertionError if Python and HACS disagree."""
    t0 = time.perf_counter()
    bound = -(-k * psi(D) // 12)
    primes = _prime_list(D, l, bound)
    while len(primes) < MIN_PRIMES:
        primes += _next_primes(D, l, primes, 1)
    # grow until the Z-lattice T is stable under adding `extra` further primes
    stable, bundle = False, None
    while True:
        mats, info = definite_matrices(D, k, primes)
        basis = z_algebra(mats)
        more = _next_primes(D, l, primes, extra)
        mats2, _ = definite_matrices(D, k, primes + more)
        basis2 = z_algebra(mats2)
        if basis2 == basis:
            stable = True
            primes, mats = primes + more, mats2
            break
        primes, mats, basis = primes + more, mats2, basis2
        if max(primes) > PRIME_CAP:
            break
    r = len(basis)
    generation = {"method": "heuristic", "certified_equal": None, "note": "stable_under_extra_primes only (heuristic)"}
    if k == 2:
        h = info["h"]
        H = flint.fmpz_mat(r, h * h, [int(x) for b in basis for row in b for x in row])
        snf = H.snf()
        inv = [int(snf[i, i]) for i in range(min(r, h * h))]
        generation = {"method": "saturation", "certified_equal": bool(r == len(inv) and all(abs(x) == 1 for x in inv)),
                      "smith_invariants_all_one": all(abs(x) == 1 for x in inv), "rank": r,
                      "argument": "Smith invariants of the HNF basis of T_comp in Z^{h^2} all 1 <=> T_comp = Q T_comp cap M_h(Z) contains T contains T_comp"}
        # cheap re-check: adding T_ell changes nothing (ell prime to D at all cells of the grid)
        if D % l:
            mats_l, _ = definite_matrices(D, k, primes + [l])
            generation["T_ell_adds_nothing"] = z_algebra(mats_l) == basis
    if r > MAX_RANK:
        raise ValueError(f"cell ({D},{k},{l}): rank T = {r} exceeds the R7 literal limit {MAX_RANK}")
    C = regular_rep(basis, mats)
    Cl = [_nm(c, l) for c in C]
    # T/l: regular rep of dimension r; the algebra generated by the C_p mod l is T/l (faithful)
    # (the identity is the first Z-basis element or a combination of them; it is in F_l[ops] by the unital closure)
    blocks = split_local(Cl, l)
    t_py = time.perf_counter() - t0
    rec_blocks, gco = [], []
    for ops in blocks:
        co = _generic_coeffs(ops, l)
        gco.append(co)
    whole_py = local_invariants(Cl, l)
    src = _oc_script(l, [[[int(x) for x in row] for row in _rows(g)] for g in Cl],
                     [[_rows(g) for g in ops] for ops in blocks], gco)
    res = run_script(src, hacs=hacs, threads=threads, timeout=3600)
    whole_h = res.tags["WHOLE"][0]
    assert len(res.tags["INV"]) == len(res.tags["LOEWY"]) == len(res.tags["MINPOLY"]) == len(blocks)
    hb = {i: {"inv": res.tags["INV"][i], "loewy": res.tags["LOEWY"][i], "minpoly": res.tags["MINPOLY"][i]}
          for i in range(len(blocks))}
    assert whole_h["dim"] == r == whole_py["dim"], ("whole algebra dim", whole_h["dim"], r, whole_py["dim"])
    assert whole_h["components"] == len(blocks) == whole_py["components"], "component count disagrees"
    agree = True
    for i, ops in enumerate(blocks):
        py = local_invariants(ops, l)
        h = hb[i]
        hx = h["inv"]
        diff = _cmp_keys(py, hx)
        mp_py = _py_minpoly(ops, gco[i], l)
        if h["minpoly"] != mp_py:
            diff.append("minpoly")
        if h["loewy"]["length"] != py["nilpotency_index"]:
            diff.append("loewy_length")
        agree &= not diff
        f = hx["residue_degree"]
        eis = (k == 2) and _is_eisenstein(ops, primes, l)
        rec_blocks.append({
            "idx": i, "dim": hx["dim"], "local": hx["local"], "residue_degree": f,
            "dim_radical": hx["dim_radical"], "loewy_length": h["loewy"]["length"], "loewy_layers_over_f": h["loewy"]["layers_over_f"],
            "dim_tangent": hx["dim_tangent"], "embdim": hx["embdim"], "dim_socle": hx["dim_socle"],
            "gorenstein": hx["gorenstein"], "hilbert": hx["hilbert"], "minpoly_of_generator": h["minpoly"],
            "generator_index": gco[i].index(1), "generator_prime": primes[gco[i].index(1)],
            "etale": hx["dim_radical"] == 0, "strictly_etale": hx["dim"] == 1,
            "eisenstein": eis,
            "residue_label": _label(ops, l),
            "python": py, "disagree": diff,
        })
    assert agree, [b["disagree"] for b in rec_blocks if b["disagree"]]
    a = info["a"]
    flags = {
        "l_divides_gamma": [g for g in set(info["gammas"]) if g % l == 0],
        "l_in_Q_sqrt_a": _legendre_kind(a, l) if k > 2 else None,
        "note": "T is intrinsic (Z-algebra of the T_p in End_Q(M)); neither flag affects T (see module docstring)",
    }
    non_etale = [b["idx"] for b in rec_blocks if not b["etale"]]
    if k > 2 and not non_etale:
        generation = {"method": "etale_maximal_order", "certified_equal": True,
                      "argument": "every block etale: T_comp (x) Z_l is a maximal order, so T_l = T_comp (x) Z_l"}
    if k == 2:
        fbz = {"see": f"code/results/s06/brandt_free_block_z/D{D}_M1_k2.json"}
    else:
        fbz = {"see": None, "available": False,
               "reason": "symn.py works over Q(sqrt a) with a K-basis of V^{Gamma_c}; it provides no Z-basis of M(O_D; Sym^n)"}
    return {
        "D": D, "k": k, "ell": l,
        "algebra": "T^(D*ell) anemic: T_p, p not dividing D*ell (no T_ell, no U_D/Atkin-Lehner)",
        "generation": generation, "primes": primes, "n_primes": len(primes), "sturm_bound": bound, "stable_under_extra_primes": stable,
        "rank_T": r, "dim_M_over_Q": len(mats[0]), "info": {kk: vv for kk, vv in info.items() if kk != "gammas"},
        "gammas": info["gammas"], "flags": flags,
        "n_max_ideals": len(blocks), "blocks": rec_blocks,
        "free_block_z": fbz, "non_etale_blocks": non_etale, "has_non_etale": bool(non_etale),
        "eisenstein_non_etale": any(b["eisenstein"] and not b["etale"] for b in rec_blocks) if k == 2 else None,
        "gorenstein_flags": [b["gorenstein"] for b in rec_blocks],
        "whole_hacs": {kk: whole_h[kk] for kk in ("dim", "components", "local", "dim_radical", "nilpotency_index")},
        "python_hacs_agree": agree,
        "runtime_s": {"python_def_side_and_split": t_py, "hacs_wall": res.wall_s, "total": time.perf_counter() - t0},
    }


# ---------------------------------------------------------------------------------------------------------------------
def mazur_ells(D):
    """Primes dividing num((D-1)/12)."""
    num = Fraction(D - 1, 12).numerator
    return [p for p in range(2, num + 1) if num % p == 0 and all(p % q for q in range(2, int(p ** 0.5) + 1))]


DEFAULT_CELLS = (
    [(11, 2, 5)]
    + [(3, 12, 17), (5, 12, 29), (5, 12, 131), (7, 12, 1051)]
    + [(D, 2, l) for D in (11, 17, 19, 23, 29, 31, 37, 41, 43) for l in mazur_ells(D) if (D, l) != (11, 5)]
)


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--cells", nargs="*", help="cells as D:k:l (default: the acceptance grid)")
    ap.add_argument("--out", default=None, help="output JSON (default: code/results/s06/definite_local.json)")
    ap.add_argument("--hacs", default=None)
    ap.add_argument("--threads", type=int, default=4)
    args = ap.parse_args(argv)
    cells = [tuple(int(x) for x in c.split(":")) for c in args.cells] if args.cells else DEFAULT_CELLS
    exe = find_hacs(args.hacs)
    t0 = time.perf_counter()
    data, rts = [], {}
    for D, k, l in cells:
        rec = run_cell(D, k, l, hacs=exe, threads=args.threads)
        data.append(rec)
        rts[f"{D}:{k}:{l}"] = rec["runtime_s"]["total"]
        print(f"cell D={D} k={k} l={l}: rank T={rec['rank_T']} max ideals={rec['n_max_ideals']} non-etale={rec['non_etale_blocks']} "
              f"gorenstein={rec['gorenstein_flags']} agree={rec['python_hacs_agree']} ({rec['runtime_s']['total']:.1f}s)", flush=True)
    total = time.perf_counter() - t0
    prov = provenance(SCRIPT, {"cells": [list(c) for c in cells], "min_primes": MIN_PRIMES, "prime_cap": PRIME_CAP,
                               "primes_rule": "p prime to D*l, p <= ceil(k psi(D)/12), >= 4 primes, +2 until the Z-lattice T is stable"},
                      total, exe)
    prov["per_cell_runtime_s"] = rts
    prov["hacs_version"] = hacs_version(exe)
    prov["s06_c1_comparison"] = "OPEN: S06-C1 is not merged; Python-vs-HACS agreement here is the in-module independent route only"
    payload = {"provenance": prov, "status": "computed", "data": data}
    from .. import results

    out = pathlib.Path(args.out) if args.out else results.repo_root() / "code" / "results" / "s06" / "definite_local.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=1, sort_keys=True, default=results._default) + "\n", encoding="utf-8")
    print("wrote", out, f"({total:.1f}s)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
